    end
    remask = false;
end %[output:group:6aafe7b3]
%%
hc.log_level = -2;
remask = true;
if remask %[output:group:79357e89]
    % Cut 1
    if ~exist('cuts2fit800','var')
        [msk00,~,msk800o00_vertex] = draw_mask(w2_800o00);
        cuts2fit800.mask_ds1 = msk800o00_vertex;        
    else
        [msk00,~,msk800o00_vertex] = draw_mask(w2_800o00,'mask',cuts2fit800.mask_ds1');
    end
    wm800_o00 = mask(w2_800o00,msk00) %[output:5ef73647]
    plot(wm800_o00); lz 0 0.5; keep_figure; %[output:6d7382eb]

    % Cut 2
    wm800_om1m1 = cut(w2_800om1m1,[0,0.04,2],[]);
